class Solution {
    private final java.util.Set<Integer> seen = new java.util.HashSet<>();

    public boolean findTarget(TreeNode root, int k) {
        return dfs(root, k);
    }

    private boolean dfs(TreeNode node, int k) {
        if (node == null) {
            return false;
        }
        if (seen.contains(k - node.val)) {
            return true;
        }
        seen.add(node.val);
        return dfs(node.left, k) || dfs(node.right, k);
    }
}

class Solution {
    public boolean findTarget(TreeNode root, int k) {
        if (root == null) {
            return false;
        }
        java.util.Set<Integer> seen = new java.util.HashSet<>();
        java.util.Queue<TreeNode> queue = new java.util.ArrayDeque<>();
        queue.add(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.remove();
            if (seen.contains(k - node.val)) {
                return true;
            }
            seen.add(node.val);
            if (node.left != null) {
                queue.add(node.left);
            }
            if (node.right != null) {
                queue.add(node.right);
            }
        }
        return false;
    }
}

class Solution {
    public boolean findTarget(TreeNode root, int k) {
        java.util.List<Integer> values = new java.util.ArrayList<>();
        inorder(root, values);

        int left = 0;
        int right = values.size() - 1;
        while (left < right) {
            int sum = values.get(left) + values.get(right);
            if (sum == k) {
                return true;
            }
            if (sum < k) {
                left++;
            } else {
                right--;
            }
        }
        return false;
    }

    private void inorder(TreeNode node, java.util.List<Integer> values) {
        if (node == null) {
            return;
        }
        inorder(node.left, values);
        values.add(node.val);
        inorder(node.right, values);
    }
}

class Solution {
    public boolean findTarget(TreeNode root, int k) {
        if (root == null) {
            return false;
        }

        BstIterator low = new BstIterator(root, false);
        BstIterator high = new BstIterator(root, true);
        TreeNode left = low.next();
        TreeNode right = high.next();

        while (left != right) {
            int sum = left.val + right.val;
            if (sum == k) {
                return true;
            }
            if (sum < k) {
                if (!low.hasNext()) {
                    return false;
                }
                left = low.next();
            } else {
                if (!high.hasNext()) {
                    return false;
                }
                right = high.next();
            }
        }
        return false;
    }

    private static class BstIterator {
        private final java.util.Deque<TreeNode> stack = new java.util.ArrayDeque<>();
        private final boolean reverse;

        BstIterator(TreeNode root, boolean reverse) {
            this.reverse = reverse;
            pushPath(root);
        }

        boolean hasNext() {
            return !stack.isEmpty();
        }

        TreeNode next() {
            TreeNode node = stack.pop();
            if (reverse) {
                pushPath(node.left);
            } else {
                pushPath(node.right);
            }
            return node;
        }

        private void pushPath(TreeNode node) {
            while (node != null) {
                stack.push(node);
                node = reverse ? node.right : node.left;
            }
        }
    }
}

class Solution {
    public boolean findTarget(TreeNode root, int k) {
        return scan(root, root, k);
    }

    private boolean scan(TreeNode node, TreeNode root, int k) {
        if (node == null) {
            return false;
        }
        if (containsDifferentNode(root, k - node.val, node)) {
            return true;
        }
        return scan(node.left, root, k) || scan(node.right, root, k);
    }

    private boolean containsDifferentNode(TreeNode node, int target, TreeNode excluded) {
        if (node == null) {
            return false;
        }
        if (target < node.val) {
            return containsDifferentNode(node.left, target, excluded);
        }
        if (target > node.val) {
            return containsDifferentNode(node.right, target, excluded);
        }
        if (node != excluded) {
            return true;
        }
        return containsDifferentNode(node.left, target, excluded)
                || containsDifferentNode(node.right, target, excluded);
    }
}
